package scaffolds

import (
	"io/fs"
	"os"
	"path/filepath"
	"testing"
)

// TestVendoredPkgGenFilesPassTheHeaderRule: forge's pkg/ tree is vendored into
// every project's .forge-pkg/pkg, where `forge lint`'s scaffold-ownership lane
// walks it with LintGeneratedHeader. A pkg/ _gen.go with a non-forge header
// (pkg/fluxdelivery/template_gen.go once said "Code generated by gentemplate")
// turned every freshly scaffolded project's lint red, the whole e2e corpus with
// it. The walk opens each file itself, so the test cache sees every input.
func TestVendoredPkgGenFilesPassTheHeaderRule(t *testing.T) {
	t.Parallel()
	root := filepath.Join("..", "..", "..", "pkg")
	n := 0
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == "testdata" {
				return filepath.SkipDir
			}
			return nil
		}
		if !isGenFilename(path) {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		n++
		rel, _ := filepath.Rel(filepath.Join("..", "..", ".."), path)
		rel = filepath.Join(".forge-pkg", rel)
		for _, f := range LintGeneratedHeader(rel, data) {
			t.Errorf("%s [%s] %s", rel, f.Rule, f.Message)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if n == 0 {
		t.Fatal("found no _gen.go under pkg/: the walk is broken and would pass vacuously")
	}
}
